<template>
  <view class="student-page"><view class="safe-area" /><view class="brand-bar"><view class="brand"><text class="brand-mark">招</text><text class="brand-name">招生</text></view></view><view class="profile-hero"><view class="profile-row"><view class="avatar">{{ displayName.slice(0, 1) }}</view><view class="profile-main"><text class="name">{{ displayName }}</text><text class="school">{{ schoolAndGrade }}</text></view><text class="edit" @tap="go('/pages/common/edit-profile')">编辑资料 ›</text></view><view class="profile-note">志愿季正在进行中，完善兴趣方向后可获得更精准的咨询推荐。</view></view><view class="stats"><view class="stat" @tap="go('/pages/student/my-questions')"><text class="stat-number">{{ formatCount(questionCount) }}</text><text class="stat-label">我的咨询</text></view><view class="stat" @tap="go('/pages/common/my-favorites')"><text class="stat-number">{{ formatCount(favoriteCount) }}</text><text class="stat-label">收藏问答</text></view><view class="stat" @tap="go('/pages/common/my-comments')"><text class="stat-number">{{ formatCount(commentCount) }}</text><text class="stat-label">收到回复</text></view></view><view class="content"><view class="prep-card"><view class="prep-head"><text>我的志愿准备</text><text class="progress-status">进行中</text></view><text class="prep-copy">已完成 {{ profileDone }} / 3 项资料，继续完善可提高推荐准确度</text><view class="progress"><view class="progress-fill" :style="{ width: `${profileProgress}%` }" /></view></view><view class="section-title">咨询与内容</view><view class="menu"><view v-for="item in contentItems" :key="item.label" class="menu-row" @tap="go(item.url)"><text class="menu-icon">{{ item.icon }}</text><text class="menu-label">{{ item.label }}</text><text class="menu-hint">{{ item.hint }}</text><text class="menu-arrow">›</text></view></view><view class="logout" @tap="logout">退出登录</view></view><TabBar currentPath="/pages/student/profile" /></view>
</template>
<script setup>
import { computed, ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { useUserStore } from '@/store/modules/user'
import TabBar from '@/components/TabBar.vue'
import { getMyQuestions, getMyFavorites } from '@/api/qa'
import { getMyComments } from '@/api/comment'
import { getMyProfile } from '@/api/profile'
const userStore = useUserStore(); const questionCount = ref(0); const favoriteCount = ref(0); const commentCount = ref(0); const profileProgress = ref(0); const profileDone = ref(0)
const displayName = computed(() => userStore.userInfo?.nickname || userStore.userInfo?.name || '未登录')
const schoolAndGrade = computed(() => `${userStore.userInfo?.highSchoolName || '未绑定高中'} · ${userStore.userInfo?.grade || '未填写年级'}`)
const contentItems = computed(() => [{ icon: '◷', label: '我的咨询', hint: `${questionCount.value} 条进行中`, url: '/pages/student/my-questions' }, { icon: '☆', label: '论坛收藏', hint: `${favoriteCount.value} 条更新`, url: '/pages/common/my-favorites' }, { icon: '✦', label: '浏览记录', hint: '›', url: '/pages/common/my-comments' }, { icon: '!', label: '申诉中心', hint: '查看处理结果', url: '/pages/common/forum-penalties' }])
onShow(loadProfile)
function formatCount(value) { return String(value || 0).padStart(2, '0') }
async function loadProfile() { try { const profile = await getMyProfile(); if (profile) userStore.updateUserInfo(profile); profileDone.value = [userStore.userInfo?.nickname, userStore.userInfo?.highSchoolName, userStore.userInfo?.grade].filter(Boolean).length; profileProgress.value = Math.round((profileDone.value / 3) * 100) } catch (error) { profileDone.value = 0; profileProgress.value = 0 } try { const result = await getMyQuestions({ page: 1, size: 1 }); questionCount.value = result?.total || result?.records?.length || 0 } catch (error) { questionCount.value = 0 } try { const result = await getMyFavorites({ page: 1, size: 1 }); favoriteCount.value = result?.total || result?.records?.length || 0 } catch (error) { favoriteCount.value = 0 } try { const result = await getMyComments({ page: 1, size: 1 }); commentCount.value = result?.total || result?.records?.length || 0 } catch (error) { commentCount.value = 0 } }
function go(url) { uni.navigateTo({ url }) } function logout() { uni.showModal({ title: '退出登录', content: '确定退出当前账号吗？', success: result => { if (result.confirm) { userStore.logout?.(); uni.reLaunch({ url: '/pages/index/index' }) } } }) }
</script>
<style lang="scss" scoped>
.student-page{min-height:100vh;padding-bottom:144rpx;background:#f3f7fb;color:#172d47}.safe-area{height:calc(env(safe-area-inset-top) + 16rpx);min-height:64rpx;background:#fff}.brand-bar{display:flex;align-items:center;height:104rpx;padding:0 40rpx;background:#fff}.brand{display:flex;align-items:center;gap:14rpx}.brand-mark{display:flex;align-items:center;justify-content:center;width:54rpx;height:54rpx;border-radius:12rpx;color:#fff;background:#5b9bd5;font-size:36rpx;font-weight:800}.brand-name{font-size:36rpx;font-weight:800}.profile-hero{padding:52rpx 40rpx 70rpx;color:#fff;background:#4e91cc}.profile-row{display:flex;align-items:center}.avatar{display:flex;align-items:center;justify-content:center;flex:none;width:126rpx;height:126rpx;border:5rpx solid rgba(255,255,255,.78);border-radius:50%;background:rgba(255,255,255,.16);font-size:48rpx;font-weight:800}.profile-main{min-width:0;margin-left:28rpx}.name,.school{display:block}.name{font-size:44rpx;font-weight:800}.school{margin-top:8rpx;color:#ecf6ff;font-size:26rpx}.edit{margin-left:auto;white-space:nowrap;color:#fff;font-size:25rpx}.profile-note{margin-top:40rpx;padding:24rpx 26rpx;border-radius:14rpx;color:#f3f9ff;background:rgba(255,255,255,.16);font-size:25rpx;line-height:1.65}.stats{display:flex;overflow:hidden;margin:-4rpx 40rpx 0;border-radius:0 0 20rpx 20rpx;background:#fff}.stat{flex:1;padding:34rpx 0 30rpx;text-align:center;border-right:1rpx solid #e2eaf1}.stat:last-child{border-right:0}.stat-number,.stat-label{display:block}.stat-number{color:#397cba;font-size:46rpx;font-weight:800}.stat-label{margin-top:16rpx;color:#5f7187;font-size:25rpx}.content{padding:42rpx 40rpx 34rpx}.prep-card{padding:30rpx;border-radius:20rpx;background:#fff}.prep-head{display:flex;align-items:center;justify-content:space-between;font-size:32rpx;font-weight:800}.progress-status{padding:8rpx 14rpx;border-radius:10rpx;color:#dc8a17;background:#fff4dc;font-size:23rpx;font-weight:500}.prep-copy{display:block;margin-top:16rpx;color:#6a7e98;font-size:24rpx}.progress{height:14rpx;margin-top:28rpx;overflow:hidden;border-radius:99rpx;background:#e4edf3}.progress-fill{height:100%;border-radius:99rpx;background:#5b9bd5}.section-title{margin-top:72rpx;font-size:34rpx;font-weight:800}.menu{margin-top:26rpx}.menu-row{display:flex;align-items:center;min-height:104rpx;border-bottom:1rpx solid #dbe5ee}.menu-icon{width:42rpx;color:#2e76bc;font-size:28rpx;text-align:center}.menu-label{margin-left:18rpx;font-size:28rpx}.menu-hint{margin-left:auto;color:#4f6075;font-size:24rpx}.menu-arrow{margin-left:18rpx;color:#1b3856;font-size:34rpx}.logout{width:210rpx;margin:64rpx auto 10rpx;padding:18rpx 0;border-radius:99rpx;color:#dc615a;background:#fff0ef;font-size:26rpx;text-align:center}
</style>
